const raw = $input.first().json.stdout;
const data = JSON.parse(raw);
return data.map(item => ({ json: item }));

const catalogo = [
  { producto: 'Procesador NeuraChip AI-X100', precio: 850000, stockBase: 3 },
  { producto: 'Módulo FPGA UltraScale+ 16GB', precio: 420000, stockBase: 2 },
  { producto: 'Sensor LiDAR 3D Industrial v2', precio: 290000, stockBase: 6 },
  { producto: 'Microcontrolador STM32H7 Dual-Core', precio: 85000, stockBase: 12 },
  { producto: 'Unidad NPU Tensor Processing V2', precio: 650000, stockBase: 1 }
];

const ventas = $('Parsear Ventas (JSON)').all().map(i => i.json);

return ventas.map((v, index) => {
  // Asigna un componente del catálogo rotativamente a cada cliente
  const item = catalogo[index % catalogo.length];

  const nombreProducto = v.producto || item.producto;
  const precioUnitario = Number(v.precio) || item.precio;
  const cantidad = Number(v.cantidad) || 1;

  const stockRestante = Math.max(0, item.stockBase - cantidad);
  const totalVenta = cantidad * precioUnitario;
  const necesitaRecompra = stockRestante <= 2;

  return {
    json: {
      cliente: v.cliente || v.nombre || 'Cliente',
      email: v.email || 'sin_email@duoc.cl',
      ciudad: v.ciudad || 'Valparaíso',
      producto: nombreProducto,
      cantidad: cantidad,
      precio_unitario: precioUnitario,
      total_venta: totalVenta,
      stock_restante: stockRestante,
      requiere_recompra: necesitaRecompra ? 'SÍ (CRÍTICO)' : 'NO'
    }
  };
});

const datos = $input.all().map(item => item.json);
const jsonString = JSON.stringify(datos);

return [{
  json: { total_registros: datos.length },
  binary: {
    data: {
      data: Buffer.from(jsonString).toString('base64'),
      mimeType: 'application/json',
      fileName: 'datos_ventas.json'
    }
  }
}];

// Obtener los datos procesados de las ventas
const ventas = $items("Asignar Catálogo y Métricas").map(item => item.json);

let filasHtml = '';
ventas.forEach(v => {
  // Destacar en rojo si el stock restante es crítico (ej. <= 2)
  const alertaStock = v.stock_restante <= 2 ? 'background-color: #ffcccc; color: #990000; font-weight: bold;' : '';

  filasHtml += `
    <tr style="${alertaStock}">
      <td style="padding: 8px; border: 1px solid #ddd;">${v.cliente}</td>
      <td style="padding: 8px; border: 1px solid #ddd;">${v.email}</td>
      <td style="padding: 8px; border: 1px solid #ddd;">${v.ciudad}</td>
      <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">${v.stock_restante}</td>
    </tr>
  `;
});

const htmlFinal = `
  <h2>Reporte de Cierre Diario de Ventas</h2>
  <p>Se han procesado e insertado <b>${ventas.length} ventas</b> en MongoDB Atlas.</p>

  <table style="width: 100%; border-collapse: collapse; font-family: Arial, sans-serif;">
    <thead>
      <tr style="background-color: #004085; color: white;">
        <th style="padding: 10px; border: 1px solid #ddd;">Cliente</th>
        <th style="padding: 10px; border: 1px solid #ddd;">Email</th>
        <th style="padding: 10px; border: 1px solid #ddd;">Ciudad</th>
        <th style="padding: 10px; border: 1px solid #ddd;">Stock Restante</th>
      </tr>
    </thead>
    <tbody>
      ${filasHtml}
    </tbody>
  </table>
  <p><small>Este es un reporte automático generado por n8n.</small></p>
`;

return [{ json: { html_reporte: htmlFinal, total: ventas.length } }];
